#![cfg(feature = "app")]
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
//! Pins the bytes org-node stores and sends, so the type-level refactor of the
//! org-node type-safety change cannot silently change them (LLR-ayrdr8): the
//! postcard plaintext of a Persona store, and the postcard bodies of the two
//! kinds of Wire message and the record snapshot inside the first. (The Base64 text
//! of an Invite and a Join request was pinned here until T7 of the
//! chain-authority change; the EVM calldata of a genesis and an update until
//! T13, when the chain write moved to on-chain-client, whose `write_pure`
//! pins it.)
//!
//! Values captured on worktree-org-node-type-safety @ 813f85b (2026-10-04),
//! before the refactor, by the generator in
//! docs/plans/2026-10-04-org-node-type-safety.md (T1). Never edit this file to
//! make it pass. Each test decodes a pinned value with whatever the field
//! types are at the time, requires it to encode back to the same bytes, and
//! reads named fields through serde's data model (`serde_json::Value`), which
//! is the same for a newtype and the plain value it wraps. The first catches
//! an asymmetric encoding change; the second catches a symmetric one, such as
//! two fields swapping places, which a byte round trip alone would miss.

use org_node::service::first_admission_base;
use org_node::store::{MemberSnapshot, StoreData};
use org_node::transport::wire::{decode_body, encode_frame, WireMessage};
use serde_json::{json, Value};

// Merged 2026-10-05 into worktree-person-shared-types (master `1feb608`). The
// two pinned values below differ from master's by exactly this branch's two
// deliberate format changes, and were derived from master's bytes, not
// captured from the code: GOLDEN_STORE has one byte `00` inserted after the
// Organisation record's `proxy_account` — `org_private_key: None`, the field
// REQ-ech45n adds (LLR-3fwykc); GOLDEN_WIRE has the Envelope's 65-byte
// signature (`40` and 64 bytes) removed after its Change set bytes — the
// Envelope carries no signature (LLR-e7s4ye). Master's values:
// GOLDEN_STORE  = ""
// GOLDEN_WIRE   = ""
//
// Re-pinned 2026-10-06 (change worktree-org-node-chain-authority, T6): the
// store gains `expected_admissions` (`01` || `cc`x20 || `ee`x32 appended) and
// the Wire message `invite_id` (`01` || `ee`x32 appended); derived by the
// format rule from the values above, never captured from the code. The
// values before T6:
// GOLDEN_STORE  = ""
// GOLDEN_WIRE   = ""
//
// Re-pinned 2026-10-06, T7: `pending_invites` removed (offsets 559–675); the
// Invite and Join request values are gone with their types. Derived by the
// format rule from the T6 value, never captured from the code. The store
// value before T7:
// GOLDEN_STORE  = ""
//
// Re-pinned 2026-10-06, T8 (final for this change): the administrator key
// removed from the record (offsets 266–297); two provisional updates, a
// genesis and a Change set, between the records and the expectations — the
// store LLR-ayrdr8 names. Derived by the format rule from the T7 value (cut
// 32 bytes at 266, insert `02` ‖ genesis (224 bytes) ‖ Change set (133
// bytes) at 527), never captured from the code. The store value before T8:
// GOLDEN_STORE  = ""
// GOLDEN_STORE  = ""
//
// Re-pinned 2026-10-06 (change worktree-org-node-org-key-pair, T2): the
// Organisation secret removed from the record (`01` ‖ `44`x32 cut at offsets
// 232–264). Derived by the format rule from the value above, never captured
// from the code. GOLDEN_WIRE is unchanged: the Wire message's
// `org_private_key` holds the same option tag and 32 bytes the secret did.
// GOLDEN_STORE  = ""
// GOLDEN_WIRE   = ""
//
// Re-pinned 2026-10-06 (change worktree-org-node-org-key-pair, T3): the
// invite identifier removed — from the expectation (`ee`x32 at offsets
// 873–904, the store's last 32 bytes) and from the Wire message (`01` ‖
// `ee`x32 at 317–349, its last 33 bytes). Derived by the format rule from the
// values above, never captured from the code.
// GOLDEN_WIRE   = ""
//
// Re-pinned 2026-10-06 (change worktree-org-node-org-key-pair, T4): the Wire
// message is an enum of two kinds (LLR-js9dsu). GOLDEN_WIRE is Organisation
// information: `00` ‖ the Envelope (bytes 0–167 of the value above) ‖ the
// record snapshot without its option tag (bytes 202–316) ‖ the Organisation
// private key without its option tag (bytes 169–200). GOLDEN_REVOCATION is
// `01` ‖ the same Envelope. Derived by the format rule, never captured from
// the code. The store value before T7 of this change:
// GOLDEN_STORE  = ""
//
// Re-pinned 2026-10-06 (change worktree-org-node-org-key-pair, T7): the
// record's Organisation private key is required (LLR-byjvd9): the byte `00`
// (`org_private_key: None`) at offset 493 becomes `44`x32, the key with no
// option tag. Derived by the format rule, never captured from the code.
// GOLDEN_STORE  = ""
//
// Re-pinned 2026-10-06 (change worktree-org-node-org-key-pair, T8): a
// Change-set provisional update holds the private key of its fresh
// Organisation key pair (LLR-e2b7gv, LLR-qjz3q4): `99`x32 inserted at offset
// 883, after its Change-set bytes `04 09080706`. Derived by the format rule,
// never captured from the code. The store value before S3 T2:
// GOLDEN_STORE  = ""
//
// Re-pinned 2026-10-07 (change worktree-org-io-commit-workflow, S3 T2; owner
// ruling 12 of docs/plans/2026-10-06-org-io-commit-workflow.md: accepted,
// new pin, no migration): the Organisation record ends with
// `kept_change_set` (LLR-d9778a), here `None` — the byte `00` inserted at
// offset 525, after the record's Organisation private key (`44`x32) and
// before the provisional-update count `02`. Derived by the format rule from
// the value above, never captured from the code.
const GOLDEN_STORE: &str = "";
const GOLDEN_WIRE: &str = "";
// Re-pinned 2026-10-07 (change worktree-org-io-commit-workflow, S3 T4;
// LLR-ayrdr8 as amended that day): index 01 now precedes a revocation
// notice (LLR-dc45ur), not an Envelope. The value is derived from the
// notice's field order, never captured from the code: `01` ‖ `org_id`
// (`aa`x20) ‖ `member_id` (`02`x32) ‖ `device` (the snapshot's Device key
// `ca93…be7c` from GOLDEN_WIRE) ‖ the org-members wire proof — `default_map`
// (`ff`x32, all 256 levels default) ‖ `siblings` (`00`, none) ‖ `ending`
// (`00`, an empty leaf). The value before S3 T4 (`01` ‖ the Envelope):
// GOLDEN_REVOCATION = ""
const GOLDEN_REVOCATION: &str = "01aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa0202020202020202020202020202020202020202020202020202020202020202ca93ac1705187071d67b83c7ff0efe8108e8ec4530575d7726879333dbdabe7cffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff0000";

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

/// The value as serde's data model sees it, field names included.
fn model<T: serde::Serialize>(value: &T) -> Value {
    serde_json::to_value(value).unwrap()
}

/// verifies: LLR-ayrdr8, LLR-d9778a
#[test]
fn persona_store_plaintext_is_pinned() {
    let bytes = unhex(GOLDEN_STORE);
    let data: StoreData = postcard::from_bytes(&bytes).unwrap();
    assert_eq!(hex(&postcard::to_allocvec(&data).unwrap()), GOLDEN_STORE);

    let m = model(&data);
    let persona = &m["personas"][0];
    assert_eq!(persona["persona_id"], json!("p-alice"));
    assert_eq!(persona["org_id"][0], json!(0xaa));
    assert_eq!(persona["handle"], json!("alice"));
    assert_eq!(persona["name"], json!("Alice"));
    assert_eq!(persona["surname"], json!("Smith"));
    assert_eq!(persona["member_seed"][31], json!(0x11));
    assert_eq!(persona["device_seed"][31], json!(0x12));
    assert_eq!(persona["member_id"][0], json!(0x01));
    assert_eq!(persona["status"], json!("Active"));
    let org = &m["orgs"][0];
    assert_eq!(org["org_id"][0], json!(0xaa));
    assert_eq!(org["root_hash"][0], json!(0x33));
    assert_eq!(org["org_pub_key"][0], json!(0xd0));
    assert_eq!(org["epoch"], json!(3));
    assert!(org.get("org_secret").is_none(), "no Organisation secret (LLR-qsjde3)");
    assert_eq!(org["last_seq"], json!(2));
    assert!(org.get("admin_member_key").is_none(), "no administrator key");
    assert_eq!(org["proxy_account"][0], json!(0x55));
    assert_eq!(org["org_private_key"][0], json!(0x44), "every record holds the key (LLR-byjvd9)");
    assert_eq!(org["kept_change_set"], json!(null), "the record ends with its kept Change set (LLR-d9778a)");
    let bob = &org["trie_members"][1];
    assert_eq!(bob["id"][0], json!(0x02));
    assert_eq!(bob["handle"], json!("bob"));
    assert_eq!(bob["name"], json!("Bob"));
    assert_eq!(bob["surname"], json!("Jones"));
    assert_eq!(bob["member_key"][0], json!(0x88));
    assert_eq!(bob["device_keys"][0][0], json!(0xa0));
    assert!(m.get("pending_invites").is_none(), "no pending invites");
    let genesis = &m["provisional_updates"][0];
    assert_eq!(genesis["org_id"], json!(null));
    assert_eq!(genesis["seq"], json!(1));
    assert_eq!(genesis["change"]["Genesis"]["members"][0]["handle"], json!("alice"));
    assert_eq!(genesis["change"]["Genesis"]["org_private_key"][0], json!(0x88));
    let pu = &m["provisional_updates"][1];
    assert_eq!(pu["org_id"][0], json!(0xbb));
    assert_eq!(pu["persona_id"], json!("p-alice"));
    assert_eq!(pu["base_root"][0], json!(0x33));
    assert_eq!(pu["resulting_root"][0], json!(0x66));
    assert_eq!(pu["seq"], json!(3));
    assert_eq!(pu["org_pub_key"][0], json!(0xd0));
    assert_eq!(pu["change"]["ChangeSet"]["change_set"], json!([9, 8, 7, 6]));
    assert_eq!(pu["change"]["ChangeSet"]["org_private_key"][0], json!(0x99));
    assert_eq!(m["expected_admissions"][0]["org_id"][0], json!(0xcc));
    assert!(m["expected_admissions"][0].get("invite_id").is_none(), "an expectation names the Organisation alone");
}

// *Renamed 2026-10-06 (change worktree-org-node-org-key-pair, T4).* Was
// `admission_wire_message_is_pinned`.
/// verifies: LLR-ayrdr8, LLR-ms8njy, LLR-js9dsu
#[test]
fn organisation_information_wire_message_is_pinned() {
    let body = unhex(GOLDEN_WIRE);
    let msg = decode_body(&body).unwrap();
    let framed = encode_frame(&msg).unwrap();
    assert_eq!(hex(&framed[4..]), GOLDEN_WIRE);

    let m = model(&msg);
    let info = &m["OrgInformation"];
    assert_eq!(info["envelope"]["org_id"][0], json!(0xaa));
    assert_eq!(info["envelope"]["parent_seq"], json!(2));
    assert_eq!(info["org_private_key"][31], json!(0x44));
    assert!(info.get("invite_id").is_none() && info.get("org_secret").is_none());

    let WireMessage::OrgInformation { record_snapshot, .. } = &msg else { panic!("Organisation information") };
    let members: Vec<MemberSnapshot> = postcard::from_bytes(record_snapshot).unwrap();
    assert_eq!(postcard::to_allocvec(&members).unwrap(), *record_snapshot);
    let admin = &model(&members)[0];
    assert_eq!(admin["handle"], json!("admin"));
    assert_eq!(admin["member_key"][0], json!(0xd0));
    assert!(first_admission_base(record_snapshot).is_ok(), "the pinned snapshot rebuilds a record");
}

// *Re-pinned 2026-10-07 (change worktree-org-io-commit-workflow, S3 T4).*
// Asserted the Envelope a revocation held; it holds a notice now.
/// verifies: LLR-ayrdr8, LLR-ms8njy, LLR-js9dsu, LLR-dc45ur
#[test]
fn revocation_wire_message_is_pinned() {
    let body = unhex(GOLDEN_REVOCATION);
    let msg = decode_body(&body).unwrap();
    assert_eq!(hex(&encode_frame(&msg).unwrap()[4..]), GOLDEN_REVOCATION);
    let m = model(&msg);
    let notice = m["Revocation"].as_object().unwrap();
    let fields: Vec<&str> = notice.keys().map(String::as_str).collect();
    assert_eq!(fields.len(), 4, "org_id, member_id, device and proof, nothing else: {fields:?}");
    assert_eq!(notice["org_id"][0], json!(0xaa));
    assert!(notice.get("envelope").is_none() && notice.get("org_private_key").is_none());
    assert_eq!(body.len(), 119, "the variant index, 20 + 32 + 32 identity bytes and a 34-byte proof");
}

/// Abnormal input: a pinned value cut short is refused, never decoded into
/// something else.
/// verifies: LLR-ayrdr8
#[test]
fn truncated_pinned_values_are_refused() {
    let store = unhex(GOLDEN_STORE);
    assert!(postcard::from_bytes::<StoreData>(&store[..store.len() - 1]).is_err());
    let body = unhex(GOLDEN_WIRE);
    assert!(decode_body(&body[..body.len() - 1]).is_err());
    let body = unhex(GOLDEN_REVOCATION);
    assert!(decode_body(&body[..body.len() - 1]).is_err());
}
